{
  "items": [
    {
      "name": "Ideal.mem_span_range_iff_exists_fun",
      "module_name": "Mathlib.RingTheory.Ideal.Operations",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {R : Type u_2} [inst : Semiring R] [inst_1 : Fintype α] {x : R} {v : α → R},\n  x ∈ Ideal.span (Set.range v) ↔ ∃ c, ∑ i, c i * v i = x"
    },
    {
      "name": "Submodule.mem_span_iff_exists_finset_subset",
      "module_name": "Mathlib.LinearAlgebra.Finsupp.LinearCombination",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {M : Type u_2} [inst : Semiring R] [inst_1 : AddCommMonoid M] [inst_2 : Module R M] {s : Set M}\n  {x : M}, x ∈ Submodule.span R s ↔ ∃ f t, ↑t ⊆ s ∧ Function.support f ⊆ ↑t ∧ ∑ a ∈ t, f a • a = x"
    },
    {
      "name": "Submodule.mem_span_iff_of_fintype",
      "module_name": "Mathlib.LinearAlgebra.Finsupp.LinearCombination",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {M : Type u_2} [inst : Semiring R] [inst_1 : AddCommMonoid M] [inst_2 : Module R M] {s : Set M}\n  [inst_3 : Fintype ↑s] {x : M}, x ∈ Submodule.span R s ↔ ∃ f, ∑ a, f a • ↑a = x"
    },
    {
      "name": "Span.repr_def",
      "module_name": "Mathlib.LinearAlgebra.Finsupp.LinearCombination",
      "kind": "theorem",
      "type": "∀ (R : Type u_4) {M : Type u_5} [inst : Semiring R] [inst_1 : AddCommMonoid M] [inst_2 : Module R M] (w : Set M)\n  (x : ↥(Submodule.span R w)), Span.repr R w x = ⋯.choose"
    },
    {
      "name": "Submodule.mem_ideal_smul_span_iff_exists_sum",
      "module_name": "Mathlib.RingTheory.Ideal.Operations",
      "kind": "theorem",
      "type": "∀ {R : Type u} {M : Type v} [inst : Semiring R] [inst_1 : AddCommMonoid M] [inst_2 : Module R M] (I : Ideal R)\n  [I.IsTwoSided] {ι : Type u_4} (f : ι → M) (x : M),\n  x ∈ I • Submodule.span R (Set.range f) ↔ ∃ a, ∃ (_ : ∀ (i : ι), a i ∈ I), (a.sum fun i c => c • f i) = x"
    }
  ]
}
